const config = $input.first().json;
const queries = [
  { searchType: 'brand', query: config.brand },
  { searchType: 'competitor', query: config.competitor },
];
const sources = [
  { platform: 'linkedin', path: '/linkedin/search', creditCost: 2 },
  { platform: 'x', path: '/x/search', creditCost: 1 },
  { platform: 'reddit', path: '/reddit/search-posts', creditCost: 1 },
];
const output = [];

for (const query of queries) {
  for (const source of sources) {
    output.push({
      json: {
        searchType: query.searchType,
        query: query.query,
        platform: source.platform,
        path: source.path,
        creditCost: source.creditCost,
      },
    });
  }
}

return output;

const responses = $input.all();
const searches = $('Build searches').all();
const output = [];

for (let index = 0; index < responses.length; index++) {
  const response = responses[index].json;
  const search = searches[index].json;

  if (response.success !== true) {
    let message = 'Request failed without an API error message.';

    // Network and API errors can have different shapes, so keep a readable fallback.
    if (response.error && response.error.message) {
      message = response.error.message;
    }

    output.push({
      json: {
        kind: 'error',
        searchType: search.searchType,
        query: search.query,
        platform: search.platform,
        sourceUrl: 'https://api.sociallisteningapi.com/api/v1' + search.path,
        dedupeKey: 'error:' + Date.now() + ':' + index + ':' + search.searchType,
        message,
      },
    });
    continue;
  }

  for (const item of response.data.items) {
    output.push({
      json: {
        kind: 'result',
        searchType: search.searchType,
        query: search.query,
        platform: search.platform,
        sourceUrl: item.url,
        dedupeKey: item.url,
        title: item.content.title,
        text: item.content.text,
        author: item.author.display_name,
        publishedAt: item.published_at,
      },
    });
  }
}

return output;

const items = $input.all().map((item) => item.json);
const results = items.filter((item) => item.kind === 'result');
const failures = items.filter((item) => item.kind === 'error');

results.sort((firstItem, secondItem) => {
  return Date.parse(secondItem.publishedAt) - Date.parse(firstItem.publishedAt);
});

const lines = [
  '# Social listening review',
  '',
  'New source URLs: ' + results.length,
  'Source failures: ' + failures.length,
  '',
];

const reviewItems = results.slice(0, 12);

for (const item of reviewItems) {
  let summary = item.title || item.text || 'Post needs review';
  summary = summary.replace(/\s+/g, ' ').trim();

  if (summary.length > 180) {
    summary = summary.slice(0, 177) + '...';
  }

  lines.push(
    '- [' + item.searchType + ' · ' + item.platform + '] ' + summary +
      ' — ' + item.sourceUrl,
  );
}

if (results.length > reviewItems.length) {
  lines.push('- ' + (results.length - reviewItems.length) + ' more new posts need review.');
}

if (failures.length > 0) {
  lines.push('', '## Search gaps');

  for (const failure of failures) {
    lines.push(
      '- ' + failure.searchType + ' · ' + failure.platform + ': ' + failure.message +
        ' — ' + failure.sourceUrl,
    );
  }
}

lines.push('', 'Human review required before replying or reporting.');

return [{
  json: {
    digest: lines.join('\n'),
    newSourceCount: results.length,
    failureCount: failures.length,
  },
}];
